const root=$input.first().json; const b=(root.body&&typeof root.body==='object')?root.body:root;
const payload=(b.payload&&typeof b.payload==='object')?b.payload:b;
const company_id=(b.company_id||payload.company_id||'3034fa2d-c918-41bb-9eae-84f2e7913db8').toString();
const event_id=(b.event_id||'').toString();
const filtros=(payload.filtros&&typeof payload.filtros==='object')?payload.filtros:{};
const mensaje=(payload.mensaje||'').toString();
const cantidad=(payload.cantidad!=null)?parseInt(payload.cantidad,10):null;
const batch_size=parseInt(payload.batch_size||5,10);
const campaign_id=(payload.campaign_id||'').toString();
const test=(payload.test===true);
// Opcion A: la plataforma agenda y dispara a la hora; n8n envia al recibir.
// Candado de frescura: si el evento trae hora prevista y llega >2h tarde (n8n caido), NO enviar.
const programado_para=(payload.programado_para!=null&&payload.programado_para!=='')?payload.programado_para.toString():null;
const VENTANA_MIN=120;
let minutos_tarde=0, vencido=false;
if(programado_para){
  const t=new Date(programado_para).getTime();
  if(!isNaN(t)){ minutos_tarde=Math.round((Date.now()-t)/60000); vencido=(minutos_tarde>VENTANA_MIN); }
}
const vigente=!vencido;
return [{json:{company_id,event_id,filtros,mensaje,cantidad,batch_size,campaign_id,test,programado_para,minutos_tarde,vencido,vigente}}];

const cfg=$('Extraer campaña').first().json;
const filtros=cfg.filtros||{};
const mensaje=cfg.mensaje||'';
const cantidad=cfg.cantidad;
const batch_size=cfg.batch_size||5;
let raw=$('Leer contactos').all().map(i=>i.json);
let rows=(raw.length===1&&Array.isArray(raw[0]))?raw[0]:raw;
rows=rows.filter(r=>r&&(r.full_name||r.phone));
const norm=s=>(s||'').toString().toLowerCase().trim();
const arr=v=>Array.isArray(v)?v.map(norm):(v!=null&&v!==''?[norm(v)]:[]);
const fStatus=arr(filtros.status), fLead=arr(filtros.lead_stage), fServ=arr(filtros.service_type);
const tieneFiltros=(fStatus.length||fLead.length||fServ.length)>0;
function match(r){
  if(!tieneFiltros) return false; // FAIL-SAFE: sin filtros no selecciona a nadie
  if(fStatus.length && !fStatus.includes(norm(r.status))) return false;
  if(fLead.length && !fLead.includes(norm(r.lead_stage))) return false;
  if(fServ.length && !fServ.includes(norm(r.service_type))) return false;
  return true;
}
let todos=rows.filter(match);
let sel=(cantidad!=null?todos.slice(0,cantidad):todos).map(r=>{const primer=(r.full_name||'').trim().split(/\s+/)[0]||'';return{contact_id:r.id,telefono:r.phone,nombre:r.full_name,texto:(mensaje||'(sin mensaje)').replace(/\{nombre\}/gi,primer)};});
const num_lotes=Math.ceil(sel.length/batch_size)||0;
return [{json:{total_segmento:todos.length,a_enviar:sel.length,batch_size,num_lotes,seleccion:sel}}];

